/** Compact human countdown between now and an ISO datetime, e.g. "2d 4h" or "5m 12s". */
export function countdown(iso) {
  if (!iso) return '';
  let secs = Math.floor((new Date(iso).getTime() - Date.now()) / 1000);
  if (secs <= 0) return '0s';
  const d = Math.floor(secs / 86400);
  secs -= d * 86400;
  const h = Math.floor(secs / 3600);
  secs -= h * 3600;
  const m = Math.floor(secs / 60);
  const s = secs - m * 60;
  if (d > 0) return "".concat(d, "d ").concat(h, "h");
  if (h > 0) return "".concat(h, "h ").concat(m, "m");
  if (m > 0) return "".concat(m, "m ").concat(s, "s");
  return "".concat(s, "s");
}
export function isPast(iso) {
  return !!iso && new Date(iso).getTime() <= Date.now();
}

/** Absolute local datetime, e.g. "2026-08-23 14:30". */
export function formatDateTime(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '';
  const pad = n => String(n).padStart(2, '0');
  return "".concat(d.getFullYear(), "-").concat(pad(d.getMonth() + 1), "-").concat(pad(d.getDate()), " ").concat(pad(d.getHours()), ":").concat(pad(d.getMinutes()));
}
flarum.reg.add('ygpynet-giveaways', 'common/format', { countdown: countdown,isPast: isPast,formatDateTime: formatDateTime, });